local _b=table.concat(_c)

local function _dec(data)
    local b='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'
    data=data:gsub('[^'..b..'=]','')
    local t={}
    for i=1,#data,4 do
        local n=0
        local pad=0
        for j=0,3 do
            local ch=data:sub(i+j,i+j)
            if ch=='=' or ch=='' then
                pad=pad+1
                n=n*64
            else
                local v=(b:find(ch,1,true) or 1)-1
                n=n*64+v
            end
        end
        local c1=math.floor(n/65536)%256
        local c2=math.floor(n/256)%256
        local c3=n%256
        t[#t+1]=string.char(c1)
        if pad<2 then t[#t+1]=string.char(c2) end
        if pad<1 then t[#t+1]=string.char(c3) end
    end
    return table.concat(t)
end

local src
if crypt and crypt.base64decode then
    src = crypt.base64decode(_b)
elseif base64decode then
    src = base64decode(_b)
elseif crypt and crypt.base64 and crypt.base64.decode then
    src = crypt.base64.decode(_b)
else
    src = _dec(_b)
end

local loader = loadstring or load
local fn, err = loader(src)
if not fn then
    error('Aero failed: '..tostring(err))
end
fn()
